  if(k==='activities')return voiceFieldBlock(k,id,en,d,`<div class="voice-chips" role="group" aria-label="${T(id,en)}">${VOICE_ACTIVITY_CHIPS.map(([key,idLabel,enLabel])=>`<button type="button" class="${selected.has(key)?'on':''}" data-a="voiceChip" data-chip="activity" data-v="${key}" aria-pressed="${selected.has(key)}" ${d.busy||d.recording?'disabled':''}>${T(idLabel,enLabel)}</button>`).join('')}
   <button type="button" class="${other?'on':''}" data-a="voiceChip" data-chip="activity" data-v="__other__" aria-pressed="${other?'true':'false'}" ${d.busy||d.recording?'disabled':''}>${T('Lainnya','Other')}</button></div>
   <input class="t" id="voice-activity-other" data-voice-other="1" aria-label="${T('Kegiatan lain','Other activities')}" value="${esc(other)}" maxlength="4000" placeholder="${T('Kegiatan lain (opsional)','Other activities (optional)')}" ${d.busy||d.recording?'disabled':''}>`);
  if(k==='availability')return voiceFieldBlock(k,id,en,d,`<div class="voice-chips" role="group" aria-label="${T(id,en)}">${VOICE_DAYS.map(([key,idLabel,enLabel])=>`<button type="button" class="${days.has(key)?'on':''}" data-a="voiceChip" data-chip="day" data-v="${key}" aria-pressed="${days.has(key)}" ${d.busy||d.recording?'disabled':''}>${T(idLabel,enLabel)}</button>`).join('')}</div>`);
