tools.exec_command({cmd:"@'
import json, os
from collections import Counter
from html.parser import HTMLParser
from pathlib import Path
class Page(HTMLParser):
    def __init__(self, html):
        super().__init__(); self.tags=[]; self.feed(html)
    def handle_starttag(self, tag, attrs):
        self.tags.append((tag, dict(attrs)))
snapshots=json.loads((Path(os.environ['TEMP'])/'yolowisata-label-snapshots.json').read_text(encoding='utf-8'))
refs=set(); checked=0; groups=0
for snapshot in snapshots:
    tags=Page(snapshot['html']).tags
    counts=Counter(a['id'] for _,a in tags if 'id' in a)
    assert not [i for i,n in counts.items() if n>1], (snapshot['name'], 'duplicate IDs', counts)
    ids={a['id']:(tag,a) for tag,a in tags if 'id' in a}
    for tag,a in tags:
        if tag=='label' and 'for' in a:
            target=a['for']; refs.add(target); checked+=1
            assert counts[target]==1, (snapshot['name'], 'missing target', target)
            control,attrs=ids[target]
            assert control in ['input','select','textarea','button','meter','output','progress'], (snapshot['name'],target,control)
            assert not (control=='input' and attrs.get('type','').lower()=='hidden'), (snapshot['name'],target,'hidden input')
        for attr in ['aria-labelledby','aria-describedby']:
            for target in a.get(attr,'').split():
                assert counts[target]==1, (snapshot['name'],attr,target)
        if a.get('role')=='group' and a.get('class')=='voice-chips':
            groups+=1
            assert a.get('aria-labelledby','').startswith('voice-label-'), (snapshot['name'],a)
print(f'PASS: {len(snapshots)} snapshots; {checked} label-for associations; {groups} named chip groups; zero missing targets, non-labelable targets, or duplicate IDs.')
print('Verified label-for targets: '+', '.join(sorted(refs)))
