        self.assertEqual(len(self.db.rows["traveler_profiles"]), 1)
        self.assertEqual(self.mirror()["bookings"][payload["id"]], payload)

    def test_retries_do_not_duplicate_messages_bookings_or_conversations(self):
        for _ in range(3):
