async def synthesize_speech(text: str, language: str, speed: float = 1.0) -> bytes:
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    if not api_key:
        raise TTSNotConfigured

    voice_id = ELEVENLABS_VOICE_IDS[language]
    try:
